contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: hash to lock, and amount of wei to send when calling lockInGuess
    function run(bytes32 hash, uint256 sendAmount) public {
        // ensure this contract can pay sendAmount when forwarding
        require(address(this).balance >= sendAmount);

        // first ensure no prior guess for this contract address
        // on constructor deployment the mapping is zero, but we check before call
        // call lockInGuess forwarding sendAmount wei
        c.lockInGuess{value: sendAmount}(hash);

        // read observable: the stored Guess.block is exposed via public mapping getter
        uint256 storedBlock = c.guesses(address(this)).block;

        // The distinguishing rule: P requires callers to send exactly 1 ether to set up a guess
        // so storedBlock != 0 should hold exactly when sendAmount == 1 ether.
        assert((storedBlock != 0) == (sendAmount == 1 ether));
    }

    // allow funding this contract for tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 hash, uint256 amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess{value: amount}(hash) { reverted = false; } catch { reverted = true; }
        // In the original contract P, lockInGuess succeeds exactly when amount == 1 ether.
        assert(reverted == (amount != 1 ether));
    }
    receive() external payable {}
}

