pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzzed parameters: an address actor (who will call) and a bytes32 guessHash
    function testFuzz_property(address actor, bytes32 guessHash) public {
        // keep actor non-zero and distinct from this contract to be reasonable
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // fund the actor so they can send 1 ether
        vm.deal(actor, 1 ether);

        // actor calls lockInGuess with exactly 1 ether
        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: 1 ether}(guessHash) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded, the reference implementation always sets guesses[actor].block != 0.
        // We observe that by reading the auto-generated public getter for guesses (struct -> components)
        // The struct fields are accessible as guesses(address) returns (uint256, bytes32) ?
        // However solidity autogenerated getter returns (uint256, bytes32) in that order as defined.
        // Only assert when the call succeeded; the property is: after a successful lockInGuess call, the stored block != 0.
        if (ok) {
            (uint256 storedBlock, bytes32 storedGuess) = c.guesses(actor);
            assertTrue(storedBlock != 0);
        } else {
            // If the call reverted, the invariant about post-call state does not apply.
            assertTrue(true);
        }
    }
}

