pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: actor address and a bytes32 guess
    function testFuzz_property(address actor, bytes32 guess) public {
        // keep actor non-zero to be an EOA we can fund and prank as
        vm.assume(actor != address(0));

        // fund actor with >= 1 ether so they can call
        vm.deal(actor, 2 ether);

        // actor calls lockInGuess sending exactly 1 ether
        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: 1 ether}(guess) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded on the reference implementation, it must have recorded a
        // nonzero stored block number for that caller; we observe this via attempting to
        // call settle after advancing the block so that settle's require(block.number > storedBlock)
        // will behave differently depending on whether stored block was set.

        // Advance one block to ensure block.number > storedBlock when storedBlock was set to block.number+1
        vm.roll(block.number + 2);

        // If the prior lockInGuess call succeeded, then the reference contract will have recorded
        // a nonzero future block and settle() will NOT revert for that caller when called after advancing.
        // The mutant that omitted setting the block will leave stored block == 0, and settle() will revert
        // because it requires(guesses[msg.sender].block != 0). We thus assert that for this actor, if
        // lockInGuess succeeded, then calling settle should NOT revert (i.e., succeed) on the reference.

        if (ok) {
            vm.prank(actor);
            bool settleOk;
            try c.settle() {
                settleOk = true;
            } catch {
                settleOk = false;
            }
            // The single assertion: on the correct contract, whenever the prior lockInGuess call succeeded
            // (actor paid exactly 1 ether), then settle called after advancing blocks will not revert.
            assertTrue(settleOk);
        } else {
            // If lockInGuess didn't succeed (reverted), then there's nothing to assert about settle; we
            // still satisfy the rule vacuously by not asserting in that branch. To keep a single assert as
            // required by the harness, we skip asserting here.
            // But Forge requires at least one assert per test; the meaningful assertion is inside the ok branch.
        }
    }
}

