pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzzed params: an actor address and a pseudorandom guess value
    function testFuzz_property(address actor, bytes32 guess) public {
        // keep actor non-zero to be a valid caller
        vm.assume(actor != address(0));

        // give actor enough ETH to call lockInGuess
        vm.deal(actor, 1 ether);

        // record the current block number before the call; the call will run in the next transaction
        uint256 before = block.number;

        // perform the lockInGuess call as the actor, sending 1 ether
        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: 1 ether}(guess) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded, the reference implementation always stores a block number > the block at which the call executed (it stores block.number + 1),
        // i.e., storedBlock >= before + 1 (since block.number hasn't advanced during the call), so storedBlock > before.
        // The mutant which stores block.number (current block) will make storedBlock == before for inputs where the call succeeds.
        if (ok) {
            // read the stored block via the public getter for the mapping: guesses(address).block is accessible through the autogenerated getter
            // The mapping has a struct; the getter is guesses(address) returning (uint256, bytes32) in some order (struct fields).
            // Since the source defines struct Guess { uint block; bytes32 guess; }
            // The autogenerated getter signature is guesses(address) returns (uint256, bytes32)
            (uint256 storedBlock, bytes32 storedGuess) = c.guesses(actor);
            // General property: for the correct contract, storedBlock > before
            assertTrue(storedBlock > before);
            // also sanity-check that storedGuess equals the supplied guess (not required by the single assertion rule, but harmless)
            // Note: We must have exactly one assertTrue per instructions — keep only the required assertion above.
        } else {
            // If the call reverted, we cannot observe storedBlock; still, the universal property only applies to successful calls.
            // To satisfy the requirement of exactly one assertion reading c, assert a tautology via c's balance behavior would be disallowed.
            // Therefore, in the revert case, simply return without asserting.
            return;
        }
    }
}
